INSERT INTO feature VALUES('oracle-modalities','checking','Oracle modalities',NULL,'partial','notable',NULL,'The certificate and elaborator regimes as two oracle disciplines over one substrate, with replay as evaluation. The property grade holds on both sides: a replayed verdict adds no data, so the bridge skips a certificate whose step and instance it has replayed, and a wildcard `_` is a problem the elaborator answers only where the equations force its term, emitting the body with that term written. The oracle modality of a container is a value in a source: its computation trees with their bind and fold, the least modality that forces the container, and an oracle algebra whose two sheaf equations are `Path` fields. A presentation of its sheafification has no form, and the modality as a record value takes a fixed container only.','kernel-core theory-coherent-resolutions core-checker surface-lowering','crates/kernel-core/tests/replay_laws.rs crates/core-checker-bridge/src/bridge/tests.rs::a_skipped_repeat_records_what_its_own_replay_records_528 corpus/model/holes/wildcard.gandr corpus/model/effects/oracle-sheaves.gandr corpus/pathological/effects/oracle-sheaves.gandr','crate-tests','#313 #528');
